css:
@page { size: 90mm 50mm; margin: 3mm; }
.print-format { page-width: 90mm; page-height: 50mm; margin-top: 3mm; margin-bottom: 3mm; margin-left: 3mm; margin-right: 3mm; font-family: "IBM Plex Sans Arabic", "Noto Sans Arabic", Arial, sans-serif; padding: 0; font-size: 10px; line-height: 1.4; color: #111827; }
.md-label-heading { width: 100%; border-bottom: 1px solid #1a375b; margin-bottom: 6px; }
.md-label-heading td { vertical-align: middle; padding-bottom: 6px; }
.md-label-title { font-size: 10px; color: #566477; margin-bottom: 4px; }
.md-label-ref { direction: ltr; unicode-bidi: bidi-override; display: inline-block; font-size: 13px; font-weight: bold; }
.md-label-qr { width: 21mm; height: 21mm; }
.md-label-docs { margin: 4px 0; padding-inline-start: 16px; font-size: 9px; }
.md-label-docs .md-label-ref { font-size: 9px; font-weight: normal; }

.md-label-docs li { break-inside: avoid; page-break-inside: avoid; }

.md-envelope-label { break-inside: avoid; page-break-inside: avoid; }
.md-envelope-label:not(:last-of-type) { break-after: page; page-break-after: always; }

html:
{% set groups = doc.envelope_documents | batch(3) | list %}
{% if not groups %}{% set groups = [[]] %}{% endif %}
{% for group in groups %}
<div class="print-format md-envelope-label" dir="{{ 'rtl' if is_rtl() else 'ltr' }}">
 <table class="md-label-heading"><tr><td><div class="md-label-title">{{ _("Envelope") }}</div><span class="md-label-ref">{{ doc.envelope_no or doc.name }}</span><div>{{ _("Documents") }}: {{ doc.envelope_documents | length }}</div><div class="md-label-title">{{ _("Label {0} of {1}").format(loop.index, loop.length) }}</div></td>
 <td style="width:23mm;text-align:center"><img class="md-label-qr" src="{{ qr_data_uri(doc.envelope_no or doc.name) }}" alt="{{ _('Tracking QR Code') }}"></td></tr></table>
 <ul class="md-label-docs">{% for row in group %}<li><span class="md-label-ref">{{ row.correspondence }}</span>{% if row.party %} · {{ row.party }}{% endif %}</li>{% endfor %}</ul>
</div>
{% endfor %}
